export type PortfolioCategory = "shopify" | "wordpress";

export interface PortfolioItem {
  name: string;
  slug: string;
  category: PortfolioCategory;
  featuredImage: string;
  hasDetailPage: boolean;
  order: number;
}

import Image from "next/image";
import Link from "next/link";
import type { PortfolioItem } from "@/types/portfolio";
import styles from "./portfolio-card.module.css";

const CATEGORY_LABELS: Record<string, string> = {
  shopify: "Shopify",
  wordpress: "WordPress",
};

export function PortfolioCard({ item }: { item: PortfolioItem }) {
  const inner = (
    <article className={styles.card}>
      <div className={styles.imageWrapper}>
        <Image
          src={item.featuredImage}
          alt={`${item.name} — Boldteq portfolio project`}
          fill
          sizes="(max-width: 640px) 100vw, (max-width: 1024px) 50vw, 33vw"
          className={styles.image}
          loading="lazy"
        />
        <span className={`${styles.badge} ${styles[`badge--${item.category}`]}`}>
          {CATEGORY_LABELS[item.category]}
        </span>
      </div>
      <div className={styles.footer}>
        <p className={styles.name}>{item.name}</p>
        {item.hasDetailPage && (
          <span className={styles.viewLink} aria-hidden="true">
            View project →
          </span>
        )}
      </div>
    </article>
  );

  if (item.hasDetailPage) {
    return (
      <Link
        href={`/our-works/${item.slug}`}
        className={styles.linkWrapper}
        aria-label={`View ${item.name} project`}
      >
        {inner}
      </Link>
    );
  }

  return <div className={styles.linkWrapper}>{inner}</div>;
}

/* ============================================================
   PortfolioCard — portfolio-card.module.css
   ============================================================ */

.linkWrapper {
  display: block;
  text-decoration: none;
  color: inherit;
}

.card {
  background-color: #fff;
  border-radius: 12px;
  overflow: hidden;
  box-shadow: 0 1px 4px rgba(0, 0, 0, 0.08);
  transition: transform 0.2s ease, box-shadow 0.2s ease;
  cursor: default;
}

.linkWrapper:is(a) .card {
  cursor: pointer;
}

.linkWrapper:is(a):hover .card {
  transform: translateY(-4px) scale(1.01);
  box-shadow: 0 8px 24px rgba(9, 34, 69, 0.14);
}

/* 4:3 aspect ratio image container */
.imageWrapper {
  position: relative;
  width: 100%;
  aspect-ratio: 4 / 3;
  overflow: hidden;
  background-color: #f5f7fa;
}

.image {
  object-fit: cover;
  transition: transform 0.3s ease;
}

.linkWrapper:is(a):hover .image {
  transform: scale(1.04);
}

/* Category badge — top-left overlay */
.badge {
  position: absolute;
  top: 12px;
  left: 12px;
  z-index: 1;
  font-family: 'Roobert PRO', Arial, sans-serif;
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 0.04em;
  text-transform: uppercase;
  border-radius: 6px;
  padding: 4px 10px;
  line-height: 1.4;
}

.badge--shopify {
  background-color: #d4f1e1;
  color: #0a6635;
}

.badge--wordpress {
  background-color: #dbeafe;
  color: #1e40af;
}

/* Card footer */
.footer {
  padding: 14px 16px 16px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
}

.name {
  font-family: 'Roobert PRO', Arial, sans-serif;
  font-size: 15px;
  font-weight: 600;
  color: #092245;
  margin: 0;
  line-height: 1.3;
}

.viewLink {
  font-family: 'Roobert PRO', Arial, sans-serif;
  font-size: 13px;
  font-weight: 500;
  color: #019ae6;
  white-space: nowrap;
  flex-shrink: 0;
}

"use client";

import type { PORTFOLIO_CATEGORIES } from "@/lib/constants/portfolio";
import styles from "./portfolio-filter.module.css";

type Category = (typeof PORTFOLIO_CATEGORIES)[number];

interface PortfolioFilterProps {
  categories: Category[];
  active: string;
  search: string;
  onCategoryChange: (cat: string) => void;
  onSearchChange: (query: string) => void;
}

export function PortfolioFilter({
  categories,
  active,
  search,
  onCategoryChange,
  onSearchChange,
}: PortfolioFilterProps) {
  return (
    <div className={styles.wrapper}>
      {/* Filter buttons */}
      <div className={styles.filters} role="group" aria-label="Filter by category">
        {categories.map((cat) => (
          <button
            key={cat.slug}
            type="button"
            onClick={() => onCategoryChange(cat.slug)}
            className={`${styles.filterBtn} ${active === cat.slug ? styles.filterBtnActive : ""}`}
            aria-pressed={active === cat.slug}
          >
            {cat.name}
          </button>
        ))}
      </div>

      {/* Search input */}
      <div className={styles.searchWrapper}>
        <span className={styles.searchIcon} aria-hidden="true">
          <svg
            xmlns="http://www.w3.org/2000/svg"
            width="16"
            height="16"
            viewBox="0 0 24 24"
            fill="none"
            stroke="currentColor"
            strokeWidth="2"
            strokeLinecap="round"
            strokeLinejoin="round"
          >
            <circle cx="11" cy="11" r="8" />
            <line x1="21" y1="21" x2="16.65" y2="16.65" />
          </svg>
        </span>
        <input
          type="search"
          placeholder="Search projects..."
          value={search}
          onChange={(e) => onSearchChange(e.target.value)}
          className={styles.searchInput}
          aria-label="Search portfolio projects"
        />
        {search && (
          <button
            type="button"
            onClick={() => onSearchChange("")}
            className={styles.clearBtn}
            aria-label="Clear search"
          >
            <svg
              xmlns="http://www.w3.org/2000/svg"
              width="14"
              height="14"
              viewBox="0 0 24 24"
              fill="none"
              stroke="currentColor"
              strokeWidth="2"
              strokeLinecap="round"
              strokeLinejoin="round"
            >
              <line x1="18" y1="6" x2="6" y2="18" />
              <line x1="6" y1="6" x2="18" y2="18" />
            </svg>
          </button>
        )}
      </div>
    </div>
  );
}

/* ============================================================
   PortfolioFilter — portfolio-filter.module.css
   ============================================================ */

.wrapper {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 16px;
  margin-bottom: 36px;
}

/* Filter pill row */
.filters {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  align-items: center;
}

.filterBtn {
  font-family: 'Roobert PRO', Arial, sans-serif;
  font-size: 14px;
  font-weight: 600;
  color: #092245;
  background-color: #fff;
  border: 1.5px solid #e5e7eb;
  border-radius: 999px;
  padding: 8px 20px;
  cursor: pointer;
  transition: background-color 0.15s ease, border-color 0.15s ease, color 0.15s ease;
  line-height: 1.4;
}

.filterBtn:hover:not(.filterBtnActive) {
  background-color: #ecf7fd;
  border-color: #019ae6;
  color: #019ae6;
}

.filterBtnActive {
  background: linear-gradient(90deg, #21cfff, #019ae6);
  border-color: transparent;
  color: #fff;
}

/* Search input */
.searchWrapper {
  position: relative;
  display: flex;
  align-items: center;
  margin-left: auto;
}

.searchIcon {
  position: absolute;
  left: 12px;
  color: #6b7280;
  display: flex;
  align-items: center;
  pointer-events: none;
}

.searchInput {
  font-family: 'Roobert PRO', Arial, sans-serif;
  font-size: 14px;
  color: #092245;
  background-color: #fff;
  border: 1.5px solid #e5e7eb;
  border-radius: 999px;
  padding: 8px 36px 8px 36px;
  width: 220px;
  outline: none;
  transition: border-color 0.15s ease, box-shadow 0.15s ease;
}

.searchInput::placeholder {
  color: #9ca3af;
}

.searchInput:focus {
  border-color: #21cfff;
  box-shadow: 0 0 0 3px rgba(33, 207, 255, 0.15);
}

/* Hide browser-native search clear button */
.searchInput::-webkit-search-cancel-button {
  display: none;
}

.clearBtn {
  position: absolute;
  right: 12px;
  background: none;
  border: none;
  padding: 0;
  display: flex;
  align-items: center;
  color: #6b7280;
  cursor: pointer;
  transition: color 0.15s ease;
}

.clearBtn:hover {
  color: #092245;
}

/* ============================================================
   max-width: 640px (mobile)
   ============================================================ */
@media screen and (max-width: 640px) {
  .wrapper {
    flex-direction: column;
    align-items: flex-start;
  }

  .searchWrapper {
    margin-left: 0;
    width: 100%;
  }

  .searchInput {
    width: 100%;
  }
}

"use client";

import { useState, useMemo } from "react";
import { PORTFOLIO_ITEMS, PORTFOLIO_CATEGORIES } from "@/lib/constants/portfolio";
import { PortfolioFilter } from "./portfolio-filter";
import { PortfolioCard } from "./portfolio-card";
import styles from "./portfolio-grid.module.css";

export function PortfolioGrid() {
  const [activeCategory, setActiveCategory] = useState<string>("all");
  const [searchQuery, setSearchQuery] = useState<string>("");

  const filtered = useMemo(() => {
    return PORTFOLIO_ITEMS.filter((item) => {
      const matchesCategory =
        activeCategory === "all" || item.category === activeCategory;
      const normalizedQuery = searchQuery.trim().toLowerCase();
      const matchesSearch =
        normalizedQuery === "" ||
        item.name.toLowerCase().includes(normalizedQuery) ||
        item.category.toLowerCase().includes(normalizedQuery);
      return matchesCategory && matchesSearch;
    });
  }, [activeCategory, searchQuery]);

  return (
    <section className={styles.section}>
      <div className={styles.container}>
        <PortfolioFilter
          categories={PORTFOLIO_CATEGORIES}
          active={activeCategory}
          search={searchQuery}
          onCategoryChange={setActiveCategory}
          onSearchChange={setSearchQuery}
        />

        <p className={styles.resultCount}>
          {filtered.length === 1
            ? "1 project"
            : `${filtered.length} projects`}
          {(activeCategory !== "all" || searchQuery.trim() !== "") && (
            <button
              type="button"
              onClick={() => {
                setActiveCategory("all");
                setSearchQuery("");
              }}
              className={styles.resetBtn}
            >
              Clear filters
            </button>
          )}
        </p>

        {filtered.length === 0 ? (
          <div className={styles.emptyState}>
            <div className={styles.emptyIcon} aria-hidden="true">
              <svg
                xmlns="http://www.w3.org/2000/svg"
                width="48"
                height="48"
                viewBox="0 0 24 24"
                fill="none"
                stroke="currentColor"
                strokeWidth="1.25"
                strokeLinecap="round"
                strokeLinejoin="round"
              >
                <rect x="3" y="3" width="7" height="7" rx="1" />
                <rect x="14" y="3" width="7" height="7" rx="1" />
                <rect x="3" y="14" width="7" height="7" rx="1" />
                <rect x="14" y="14" width="7" height="7" rx="1" />
              </svg>
            </div>
            <h3 className={styles.emptyTitle}>No projects found</h3>
            <p className={styles.emptyDesc}>
              Try a different filter or search term.
            </p>
            <button
              type="button"
              onClick={() => {
                setActiveCategory("all");
                setSearchQuery("");
              }}
              className={styles.emptyBtn}
            >
              Show all projects
            </button>
          </div>
        ) : (
          <ul className={styles.grid} role="list">
            {filtered.map((item) => (
              <li key={item.slug}>
                <PortfolioCard item={item} />
              </li>
            ))}
          </ul>
        )}
      </div>
    </section>
  );
}

/* ============================================================
   PortfolioGrid — portfolio-grid.module.css
   ============================================================ */

.section {
  background-color: #f5f7fa;
  padding: 64px 5% 80px;
}

.container {
  max-width: 80rem;
  margin-left: auto;
  margin-right: auto;
}

/* Result count + reset row */
.resultCount {
  font-family: 'Roobert PRO', Arial, sans-serif;
  font-size: 14px;
  color: #6b7280;
  margin-bottom: 24px;
  display: flex;
  align-items: center;
  gap: 12px;
}

.resetBtn {
  font-family: 'Roobert PRO', Arial, sans-serif;
  font-size: 13px;
  font-weight: 600;
  color: #019ae6;
  background: none;
  border: none;
  padding: 0;
  cursor: pointer;
  text-decoration: underline;
  text-underline-offset: 2px;
}

