/* ============================================================
   max-width: 1024px (tablet)
   ============================================================ */
@media screen and (max-width: 1024px) {
  .grid {
    grid-template-columns: repeat(2, 1fr);
    gap: 20px;
  }
}

/* ============================================================
   max-width: 640px (mobile)
